# region: sift
def sift(raw):
    out = []
    for tok in raw:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: shape
def shape(xs, floor_=2):
    return [v for v in xs if v >= floor_]

# region: gather
def gather(xs, offset=-1):
    return [v + offset for v in xs[1:]]

# region: emit
def emit(xs):
    return {'n': len(xs), 'min': min(xs) if xs else 0, 'span': (max(xs) - min(xs)) if xs else 0}

# region: intake
def intake(summary, bar=3):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return intake(emit(gather(shape(sift(raw)))))

